import re
text=open('deliverables/plan.md',encoding='utf-8').read().splitlines()
budget=[]
for l in text:
    m=re.match(r'\|\s*(A\d|B\d|C\d|D\d|E\d)\s*\|([^|]*)\|([^|]*)\|\s*([\d,]+)\s*\|\s*([\d,]+)\s*\|\s*([\d,]+)\s*\|',l)
    if m:
        q=int(m.group(4).replace(',','')); r=int(m.group(5).replace(',','')); t=int(m.group(6).replace(',',''))
        budget.append((m.group(1),q*r,t))
print('budget lines',len(budget),'sum',sum(t for _,_,t in budget),'all calc ok',all(c==t for _,c,t in budget))
# table check
block=[]; issues=[]
for i,l in enumerate(text,1):
    if l.strip().startswith('|'):
        block.append((i,l))
    else:
        if block:
            counts={len(x[1].split('|')) for x in block}
            if len(counts)>1: issues.append((block[0][0],counts))
            block=[]
if block:
    counts={len(x[1].split('|')) for x in block}
    if len(counts)>1: issues.append((block[0][0],counts))
print('table issues',len(issues))
